INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "传闻邠岐二帅将迎驾，唐昭宗惧受迫", "start_year": 895, "end_year": 895, "time_original": "895年七月辛酉出京以前；确日未另载", "dynasty": "唐", "description": "有人传言王行瑜、李茂贞将亲来迎驾，唐昭宗担心受迫。", "phases": [], "location_name": "京师", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f76c287f-814d-52ed-b014-956812862c8b"}, {"title": "唐昭宗以两都兵自卫，出启夏门宿莎城", "start_year": 895, "end_year": 895, "time_original": "895年七月辛酉", "dynasty": "唐", "description": "唐昭宗以李筠、李居实两都兵自卫，出启夏门向南山，宿莎城镇。", "phases": [], "location_name": "启夏门、南山、莎城镇", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "28ebc0b9-04c5-51cc-a488-544737745b20"}, {"title": "扈从士民至谷口多暍死，夜遭盗掠", "start_year": 895, "end_year": 895, "time_original": "895年七月辛酉出京途中及当夜", "dynasty": "唐", "description": "士民数十万追随车驾，至谷口时史书称暍死者三分之一，当夜又遭盗贼抢掠，哭声震山谷。", "phases": [], "location_name": "谷口、南山", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "54b5133d-eb3e-5838-a771-d4afb90086f2"}, {"title": "薛王知柔先至，权知中书事及置顿使", "start_year": 895, "end_year": 895, "time_original": "895年七月出京避乱时；确日未另载", "dynasty": "唐", "description": "百官多未及扈从，户部尚书、判度支及盐铁转运使薛王李知柔先至，皇帝命其暂管中书事并任置顿使。", "phases": [], "location_name": "行在", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c255d83c-c365-5304-a5f9-5d15250b3c4c"}, {"title": "李克用入同州", "start_year": 895, "end_year": 895, "time_original": "895年七月壬戌", "dynasty": "唐", "description": "李克用进入同州。", "phases": [], "location_name": "同州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f992f95b-6496-5f9d-8590-29cb183a99dc"}, {"title": "崔昭纬徐彦若王抟至莎城", "start_year": 895, "end_year": 895, "time_original": "895年七月壬戌条；确日未另载", "dynasty": "唐", "description": "崔昭纬、徐彦若、王抟到莎城。", "phases": [], "location_name": "莎城", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c1295ec6-5ec8-540e-b763-374dc660d28f"}, {"title": "唐昭宗徙幸石门镇", "start_year": 895, "end_year": 895, "time_original": "895年七月甲子", "dynasty": "唐", "description": "唐昭宗移驻石门镇。", "phases": [], "location_name": "石门镇", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "200bd989-f3ba-520e-a5c7-0040ff40bc7b"}, {"title": "李知柔刘光裕奉命还京制置宫禁守卫", "start_year": 895, "end_year": 895, "time_original": "895年七月甲子徙石门条", "dynasty": "唐", "description": "唐昭宗命薛王李知柔与知枢密院刘光裕回京城，安排宫禁守卫。", "phases": [], "location_name": "京城、宫禁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "b9e3dfd8-85a1-5b94-a6be-c15b6aee598f"}, {"title": "李克用遣判官王瑰奉表问起居", "start_year": 895, "end_year": 895, "time_original": "895年七月丙寅", "dynasty": "唐", "description": "李克用派节度判官王瑰奉表询问皇帝起居。", "phases": [], "location_name": "行在", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "673368b6-d0ab-59fd-8566-036bce8872b3"}, {"title": "郗廷昱赍诏，令李克用王珂各万骑赴新平", "start_year": 895, "end_year": 895, "time_original": "895年七月丁卯", "dynasty": "唐", "description": "唐昭宗派内侍郗廷昱带诏到李克用军，命李克用、王珂各发万骑赴新平。", "phases": [], "location_name": "李克用军、新平", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e1b3aa26-6d0f-594d-abea-9b65b7218dae"}, {"title": "诏张鐇以泾原兵控扼凤翔", "start_year": 895, "end_year": 895, "time_original": "895年七月丁卯条；确日未另载", "dynasty": "唐", "description": "唐昭宗诏彰义节度使张鐇以泾原兵控制凤翔方向。", "phases": [], "location_name": "泾原、凤翔", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "42d8f5ee-0839-5696-b767-b80b5c81ac76"}, {"title": "李克用遣兵攻华州，韩建质问", "start_year": 895, "end_year": 895, "time_original": "895年七月石门发诏后条；确日未载", "dynasty": "唐", "description": "李克用派兵攻华州，韩建登城称对李公未失礼，质问受攻之由。", "phases": [], "location_name": "华州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "b623a99d-f9b9-52b2-832f-78953ee98e66"}, {"title": "李克用答韩建逼逐天子为无礼", "start_year": 895, "end_year": 895, "time_original": "895年七月攻华州时；确日未載", "dynasty": "唐", "description": "李克用使人答韩建，责其身为臣而逼逐天子，不当以有礼自居。", "phases": [], "location_name": "华州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "fed20cdb-2fee-5283-a7ea-0d77a1cc5f77"}, {"title": "郗廷昱至，报邠岐军欲迎驾", "start_year": 895, "end_year": 895, "time_original": "895年七月李军攻华州时；确日未载", "dynasty": "唐", "description": "郗廷昱到李克用处，报告李茂贞领三万兵到盩厔，王行瑜领兵到兴平，皆欲迎驾。", "phases": [], "location_name": "华州、盩厔、兴平", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "8f4f724c-bd2c-5621-8947-31e7248e93ca"}, {"title": "李克用解华州围，移营渭桥", "start_year": 895, "end_year": 895, "time_original": "895年七月受郗报告后；确日未载", "dynasty": "唐", "description": "李克用解除华州之围，将军队移营渭桥。", "phases": [], "location_name": "华州、渭桥", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7c7c6dea-de31-5182-a14f-aa08ea20525b"}, {"title": "李知柔授清海节度使同平章事，暂留京职", "start_year": 895, "end_year": 895, "time_original": "895年七月条；确日未载", "dynasty": "唐", "description": "朝廷任薛王李知柔为清海节度使、同平章事，仍暂管京兆尹、判度支、盐铁转运使，待皇帝返京后赴镇。", "phases": [], "location_name": "清海、京兆、朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "9e08e440-a6a4-5f39-b242-698c1763ca60"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

