INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "有人传言王行瑜、李茂贞将亲来迎驾，唐昭宗担心受迫。", "citation": "卷260·乾宁二年（895）·zztj-v260-y0895-p033·原文件第38行", "note": "原文：或传王行瑜、李茂贞欲自来迎车驾，上惧为所迫；核对说明：或传保传闻，不写二帅此时已到京；帝担忧受迫不作已被劫。", "status": "draft", "id": "61878e21-1137-5046-970c-e2ecbc1039ed", "subject_id": "f76c287f-814d-52ed-b014-956812862c8b", "source_id": "102350a3-9991-5de4-9e22-60443453dfcc"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "895年七月辛酉出京以前；确日未另载", "citation": "卷260·乾宁二年（895）·zztj-v260-y0895-p033·原文件第38行", "note": "原文：或传王行瑜、李茂贞欲自来迎车驾，上惧为所迫；核对说明：或传保传闻，不写二帅此时已到京；帝担忧受迫不作已被劫。", "status": "draft", "id": "8ae87d0c-7b4e-51a7-9d5c-fc157ebb99a5", "subject_id": "f76c287f-814d-52ed-b014-956812862c8b", "source_id": "102350a3-9991-5de4-9e22-60443453dfcc"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记李杰：闻传言而惧者。", "citation": "卷260·乾宁二年（895）·zztj-v260-y0895-p033·原文件第38行", "note": "原文：或传王行瑜、李茂贞欲自来迎车驾，上惧为所迫，辛酉，以筠、居实两都兵自卫，出启夏门，趣南山，宿莎城镇。士民追从车驾者数十万人，比至谷口，暍死者三之一，夜，复为盗所掠，哭声震山谷。时百官多扈从不及，户部尚书、判度支及盐铁转运使薛王知柔独先至，上命权知中书事及置顿使。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "dfee6a52-c77e-5523-814a-5787b1525c0b", "subject_id": "48935190-c754-5bda-bdcd-382c77cb2de0", "source_id": "102350a3-9991-5de4-9e22-60443453dfcc"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "唐昭宗：闻传言而惧者。", "citation": "卷260·乾宁二年（895）·zztj-v260-y0895-p033·原文件第38行", "note": "原文：或传王行瑜、李茂贞欲自来迎车驾，上惧为所迫；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "9f82c7fe-c2ba-509c-a2b2-a80e5b3542c3", "subject_id": "8b817b16-39ce-5911-b814-6de4fdda47cd", "source_id": "102350a3-9991-5de4-9e22-60443453dfcc"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记王行瑜：传言中的迎驾者。", "citation": "卷260·乾宁二年（895）·zztj-v260-y0895-p033·原文件第38行", "note": "原文：或传王行瑜、